type PageView = {
  path: string;
};

type PageViewPayload = {
  event: 'page_view';
  path: string;
  viewedAt: string;
};

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT;

export async function logPageView({ path }: PageView): Promise<void> {
  if (!ANALYTICS_ENDPOINT) {
    console.info(`[analytics] ANALYTICS_ENDPOINT is not set. Skipping "${path}".`);
    return;
  }

  const payload: PageViewPayload = {
    event: 'page_view',
    path,
    viewedAt: new Date().toISOString(),
  };

  try {
    const response = await fetch(ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(payload),
      cache: 'no-store',
    });

    if (!response.ok) {
      console.error(`[analytics] Request failed with status ${response.status}.`);
    }
  } catch (error) {
    console.error('[analytics] Request failed.', error);
  }
}

